def f(x,n=2):return '—' if x is None else f'{x:.{n}f}'
def interval(v):
 if not v or v['ratio'] is None:return 'undefined'
 return f(v['ratio'],3)+' ['+', '.join(f(x,3) for x in v['ci95'])+']' if v['ci95'] else f(v['ratio'],3)
