def main():
 r=RESULTS;data=load('final_analysis_corrected/analysis.json');cases=read_cases(r/'final_analysis_corrected/case_level.json.gz');budget=load('BUDGET_REPORT.json');api=load('API_METHODS.json');resources=read_cases(r/'resources/results.json.gz');pred=read_cases(r/'prediction_audit.json.gz');live=read_cases(r/'live_latency/results.json.gz');trade=load('tradeoffs.json');paths=[load(folder+'/independent_paths.json') for folder in ['final_native','aux_native','goal_only_counts','bounds_native','paper_denominator_corrected','vm_controls']];reference=read_cases(r/'independent_reference.json.gz');stress=read_cases(r/'fuzz_correctness.json.gz');waypoints=load('guidance_audit/waypoints.json');seeds=read_cases(r/'guidance_audit/seed_search.json.gz');ceiling=read_cases(r/'envelope_ceiling_validation.json.gz')['summary']
